            parent[neighbor] = node;
            queue.offer(neighbor);
        }
    }

    // Now process in reverse order (post-order)
    // For each node, determine if its subtree has any apple
    // If yes, and it's not the root, we need to add 2 (for the edge to parent)

    boolean[] subtreeHasApple = new boolean[n];
    for (int i = 0; i < n; i++) {
