    }

    int totalTime = 0;

    // Process in reverse order (excluding root)
    for (int i = order.size() - 1; i >= 0; i--) {
        int node = order.get(i);
        // Propagate apple status to parent
        if (parent[node] != -1) {
            if (subtreeHasApple[node]) {
                subtreeHasApple[parent[node]] = true;
                totalTime += 2;
            }
        }
    }

    return totalTime;
