    // n=3: (9-1)/4 = 8/4 = 2. Correct.
    // n=6: (6/2)^2 = 9. Correct.

    if (n % 2 == 0) {
        int k = n / 2;
        return k * k;
    } else {
        int k = (n - 1) / 2;
        return k * (k + 1);
