    // Distribute from the end to keep the string lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(remaining, 25); // max we can add to a character is 25 (from 'a' to 'z')
        result[i] = (char) (result[i] + add);
        remaining -= add;
    }
    return new String(result);
}

